1	import { createHash } from "node:crypto";
2	import {
3	  type Collection,
4	  type Db,
5	  type Document,
6	  MongoServerError,
7	  ObjectId,
8	} from "mongodb";
9	import { getCollections } from "./collections";
10	import {
11	  engagementSchema,
12	  organizationSchema,
13	  personSchema,
14	} from "./schemas/entities";
15	import { type Fact, factAnchorsSchema, factSchema } from "./schemas/facts";
16	import type { EntityDraft, FactDraft, Proposal } from "./schemas/proposals";
17	
18	// The review queue's single write path: capture → proposal → HUMAN CONFIRMS →
19	// fact. Everything that turns drafts into knowledge goes through here, so the
20	// invariant "only the review queue writes knowledge" has one tested choke
21	// point instead of being re-implemented per server action.
22	//
23	// Crash safety without transactions: entity/fact _ids are derived
24	// deterministically from (proposalId, draft), so a re-run after a mid-write
25	// crash re-attempts the same inserts, duplicate keys are treated as already
26	// done, and per-draft resolutions record progress. Validation is all-or-
27	// nothing and runs before the first write.
28	
29	export interface EntityDecision {
30	  action: "confirm" | "discard";
31	  /** Overrides merged over the draft's data before validation (UI edits). */
32	  data?: Record<string, unknown>;
33	  draftId: string;
34	}
35	
36	export interface FactDecision {
37	  action: "confirm" | "discard" | "edit";
38	  /** Required for "edit": the corrected statement. */
39	  finalText?: string;
40	  /** Index into proposal.factDrafts — fact drafts carry no ids. */
41	  index: number;
42	}
43	
44	export interface ResolveProposalItemsInput {
45	  entities?: EntityDecision[];
46	  facts?: FactDecision[];
47	  proposalId: ObjectId;
48	  resolvedBy: string;
49	}
50	
51	export interface ResolveProposalItemsResult {
52	  createdEntityIds: Record<string, ObjectId>;
53	  createdFactIds: ObjectId[];
54	  /** True when no pending drafts remain on the proposal. */
55	  proposalResolved: boolean;
56	}
57	
58	const BASE_KEYS = {
59	  _id: true,
60	  createdAt: true,
61	  tenantId: true,
62	  updatedAt: true,
63	} as const;
64	
65	const entityInputSchemas = {
66	  engagement: engagementSchema.omit(BASE_KEYS),
67	  organization: organizationSchema.omit(BASE_KEYS),
68	  person: personSchema.omit(BASE_KEYS),
69	} as const;
70	
71	const deterministicId = (seed: string): ObjectId =>
72	  new ObjectId(createHash("md5").update(seed).digest("hex").slice(0, 24));
73	
74	const insertIgnoringDuplicate = async <T extends Document>(
75	  collection: Collection<T>,
76	  doc: T
77	): Promise<void> => {
78	  try {
79	    await collection.insertOne(doc as never);
80	  } catch (error) {
81	    const alreadyDone =
82	      error instanceof MongoServerError && error.code === 11_000;
83	    if (!alreadyDone) {
84	      throw error;
85	    }
86	  }
87	};
88	
89	interface PlannedEntity {
90	  decision: EntityDecision;
91	  doc: Document;
92	  draft: EntityDraft;
93	  entityId: ObjectId;
94	}
95	
96	interface PlannedFact {
97	  decision: FactDecision;
98	  draft: FactDraft;
99	  factDoc: Fact;
100	  factId: ObjectId;
101	}
102	
103	const resolveDraftAnchors = (
104	  draft: FactDraft,
105	  index: number,
106	  entityIdByDraftId: Map<string, ObjectId>
107	) => {
108	  const resolveRef = (kind: string, draftId: string | undefined) => {
109	    if (draftId === undefined) {
110	      return;
111	    }
112	    const entityId = entityIdByDraftId.get(draftId);
