// Spike A: AssemblyAI EU data-residency smoke test (async path only).
// Run: ASSEMBLYAI_API_KEY=... bun assemblyai-eu-smoke.ts [audio-file]
// Raw HTTP against the EU endpoint — no SDK, per the integration template.

const KEY = process.env.ASSEMBLYAI_API_KEY;
if (!KEY) {
  console.error("ASSEMBLYAI_API_KEY is required");
  process.exit(1);
}
const BASE = process.env.ASSEMBLYAI_BASE_URL ?? "https://api.eu.assemblyai.com";
const audioPath = process.argv[2] ?? new URL("memo.wav", import.meta.url).pathname;

const headers = { authorization: KEY };

console.log(`endpoint: ${BASE}`);
console.log(`audio:    ${audioPath}`);

// 1. Upload the audio bytes.
const audio = await Bun.file(audioPath).arrayBuffer();
const uploadRes = await fetch(`${BASE}/v2/upload`, {
  body: audio,
  headers: { ...headers, "content-type": "application/octet-stream" },
  method: "POST",
});
if (!uploadRes.ok) {
  console.error(`upload failed: ${uploadRes.status} ${await uploadRes.text()}`);
  process.exit(1);
}
const { upload_url } = (await uploadRes.json()) as { upload_url: string };
console.log(`uploaded: ${upload_url}`);

// 2. Create the transcript job. Minimal, documented params only — the goal is
// residency + auth + German quality, not template parity.
const createRes = await fetch(`${BASE}/v2/transcript`, {
  body: JSON.stringify({
    audio_url: upload_url,
    language_detection: true,
    speaker_labels: true,
  }),
  headers: { ...headers, "content-type": "application/json" },
  method: "POST",
});
if (!createRes.ok) {
  console.error(`create failed: ${createRes.status} ${await createRes.text()}`);
  process.exit(1);
}
const created = (await createRes.json()) as { id: string; status: string };
console.log(`transcript ${created.id}: ${created.status}`);

// 3. Poll until done.
const started = Date.now();
for (;;) {
  await new Promise((resolve) => setTimeout(resolve, 2000));
  const pollRes = await fetch(`${BASE}/v2/transcript/${created.id}`, {
    headers,
  });
  const t = (await pollRes.json()) as {
    error?: string;
    language_code?: string;
    status: string;
    text?: string;
    utterances?: { speaker: string; text: string }[];
  };
  if (t.status === "completed") {
    console.log(`\ncompleted in ${Math.round((Date.now() - started) / 1000)}s`);
    console.log(`language: ${t.language_code}`);
    console.log(`speakers: ${new Set((t.utterances ?? []).map((u) => u.speaker)).size}`);
    console.log(`text:\n${t.text}`);
    break;
  }
  if (t.status === "error") {
    console.error(`transcription error: ${t.error}`);
    process.exit(1);
  }
  process.stdout.write(`  ${t.status}…\n`);
  if (Date.now() - started > 180_000) {
    console.error("timed out after 180s");
    process.exit(1);
  }
}

