    return { kind: "skip", reason: parsed.data.reason };
  }
  if (parsed.data.entities.length === 0 && parsed.data.facts.length === 0) {
    return { kind: "skip", reason: "empty proposal" };
  }
  return {
    entities: parsed.data.entities,
    facts: parsed.data.facts,
    kind: "proposal",
  };
};

