      .sort({ updatedAt: -1 })
      .limit(CONTEXT_FACT_LIMIT)
      .toArray(),
  ]);

  const knownEntities: KnownEntity[] = [
    ...orgDocs.map((doc) => ({
      id: doc._id.toHexString(),
      kind: "organization" as const,
      name: doc.name,
    })),
    ...personDocs.map((doc) => ({
      id: doc._id.toHexString(),
      kind: "person" as const,
      name: doc.name,
    })),
    ...engagementDocs.map((doc) => ({
      id: doc._id.toHexString(),
