    const id =
      fact.anchors.personId ??
      fact.anchors.organizationId ??
      fact.anchors.engagementId;
    return (id && nameById.get(id.toHexString())) || "unknown";
  };

  const knownFacts: KnownFact[] = factDocs.map((doc) => ({
