    await sources.updateOne(
      { _id: sourceId, tenantId },
      {
        $set: {
          extractionAttempts: 0,
          status: "proposed",
          updatedAt: writtenAt,
        },
        $unset: { error: "" },
      }
    );
    return { proposalId, status: "proposed" };
  }

  if (parsed.kind === "skip") {
    // Nothing worth reviewing — close the pipeline without review work.
    await sources.updateOne(
      { _id: sourceId, tenantId },
      {
        $set: {
          extractionAttempts: 0,
          status: "reviewed",
          updatedAt: writtenAt,
