import { z } from "zod";
import { type FactCategory, factCategoryValues } from "./schemas/facts";

// The extraction contract, shaped by what makes memory pipelines survive
// unattended operation: the model sees the tenant's current knowledge so it
// proposes supersessions instead of duplicates, an explicit skip token keeps
// empty sources from producing empty review work, and a refusal gate keeps
// model apologies from ever being mistaken for knowledge.

export interface KnownEntity {
  id: string;
  kind: "engagement" | "organization" | "person";
  name: string;
}

export interface KnownFact {
  /** Display name of the anchoring entity, for the model's context only. */
  anchor: string;
  category: FactCategory;
  id: string;
  text: string;
}

export interface ExtractionPromptInput {
  capturedAt: Date;
  capturedBy: string;
  content: string;
  knownEntities: KnownEntity[];
  knownFacts: KnownFact[];
  sourceType: "email" | "manual" | "voice";
}

const hexObjectId = z.string().regex(/^[0-9a-f]{24}$/);

export const llmEntityDraftSchema = z.object({
  data: z.record(z.string(), z.unknown()),
  draftId: z.string().min(1),
  entityType: z.enum(["organization", "person", "engagement"]),
});
export type LlmEntityDraft = z.infer<typeof llmEntityDraftSchema>;

export const llmFactDraftSchema = z.object({
  anchors: z
    .object({
      engagementDraftId: z.string().optional(),
      engagementId: hexObjectId.optional(),
      organizationDraftId: z.string().optional(),
      organizationId: hexObjectId.optional(),
      personDraftId: z.string().optional(),
      personId: hexObjectId.optional(),
    })
    .refine((anchors) => Object.values(anchors).some(Boolean), {
      message: "A fact must anchor to an entity or entity draft",
    }),
  category: z.enum(factCategoryValues),
  confidence: z.number().min(0).max(1),
  supersedes: z.array(hexObjectId).optional(),
  text: z.string().min(1),
});
export type LlmFactDraft = z.infer<typeof llmFactDraftSchema>;

export const llmExtractionSchema = z.union([
  z.object({
    reason: z.string().default(""),
    skip: z.literal(true),
  }),
  z.object({
    entities: z.array(llmEntityDraftSchema).default([]),
    facts: z.array(llmFactDraftSchema).default([]),
  }),
]);

export type ParsedExtraction =
  | { kind: "failure"; reason: string }
  | { kind: "proposal"; entities: LlmEntityDraft[]; facts: LlmFactDraft[] }
  | { kind: "skip"; reason: string };

export const buildExtractionPrompt = ({
  capturedAt,
  capturedBy,
  content,
  knownEntities,
  knownFacts,
  sourceType,
}: ExtractionPromptInput): string => {
  const entityLines =
    knownEntities.length === 0
      ? "(none yet)"
      : knownEntities
          .map((entity) => `${entity.id} | ${entity.kind} | ${entity.name}`)
          .join("\n");
  const factLines =
    knownFacts.length === 0
      ? "(none yet)"
      : knownFacts
          .map(
            (fact) =>
              `${fact.id} | ${fact.anchor} | ${fact.category} | ${fact.text}`
          )
          .join("\n");

  return `You extract structured knowledge from business communications (German or English) for a company knowledge base. Reviewers confirm every item, so propose only what the source actually supports.

Known entities (id | type | name):
${entityLines}

Currently valid facts (id | anchor | category | text):
${factLines}

Source (type: ${sourceType}, captured by ${capturedBy} at ${capturedAt.toISOString()}):
---
${content}
---

Return ONLY JSON, no markdown fences, in exactly one of these two shapes:

1. Knowledge found:
{"entities": [{"draftId": "person-1", "entityType": "organization"|"person"|"engagement", "data": {"name": "...", ...}}], "facts": [{"text": "...", "category": "...", "confidence": 0.0-1.0, "anchors": {...}, "supersedes": ["<fact id>"]}]}

2. Nothing worth recording (greetings, scheduling chatter, no business knowledge):
{"skip": true, "reason": "..."}

Rules:
- Anchor each fact via "anchors": use a known entity id ({"organizationId": "<id>"}, {"personId": "<id>"}, {"engagementId": "<id>"}) when the name clearly matches a known entity; otherwise add an entity draft and reference it ({"personDraftId": "person-1"}).
- If a fact updates or contradicts a currently valid fact, list that fact's id in "supersedes". Do not re-state known facts unless they changed.
- Categories: ${factCategoryValues.join(" | ")}.
- Keep each fact one self-contained sentence in the source's language.
- Only ids from the lists above may appear as anchor ids or in "supersedes".`;
};

// Anchored refusal/clarification stems only — a narrow gate, so real content
// that merely mentions "sorry" is never misclassified.
const REFUSAL_REGEX =
  /^(i'?m sorry|i am sorry|i can(?:no|')t|i cannot|i will not|i won'?t|as an ai|als ki)/i;

const stripFences = (raw: string): string => {
  const trimmed = raw.trim();
  const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/);
  return fenced?.[1] ?? trimmed;
};

export const parseExtractionResponse = (raw: string): ParsedExtraction => {
  const text = stripFences(raw);
  if (REFUSAL_REGEX.test(text)) {
    return { kind: "failure", reason: `model refused: ${text.slice(0, 200)}` };
  }
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch {
    return {
      kind: "failure",
      reason: `not valid JSON: ${text.slice(0, 200)}`,
    };
  }
  const parsed = llmExtractionSchema.safeParse(json);
  if (!parsed.success) {
    return {
      kind: "failure",
      reason: `schema mismatch: ${parsed.error.message.slice(0, 500)}`,
    };
  }
  if ("skip" in parsed.data) {
    return { kind: "skip", reason: parsed.data.reason };
  }
  if (parsed.data.entities.length === 0 && parsed.data.facts.length === 0) {
    return { kind: "skip", reason: "empty proposal" };
  }
  return {
    entities: parsed.data.entities,
    facts: parsed.data.facts,
    kind: "proposal",
  };
};

import type { Db, ObjectId } from "mongodb";
import { z } from "zod";
import { getCollections } from "./collections";
import { deterministicId } from "./idempotency";
import {
  currentlyValidFilter,
  type Fact,
  factCategoryValues,
} from "./schemas/facts";
import { baseDocFields, zodObjectId } from "./schemas/shared";

// The always-loadable tier: a budgeted per-anchor summary materialized from
// currently valid facts, cheap enough to inject into any agent context or
// UI header, while the full fact set stays behind search. Deterministic
// composition — no LLM call — so a refresh is safe to run on every change.

export const dossierAnchorKinds = [
  "engagement",
  "organization",
  "person",
] as const;

export const dossierSchema = z.object({
  ...baseDocFields,
  anchor: z.object({
    id: zodObjectId,
    kind: z.enum(dossierAnchorKinds),
  }),
  content: z.string(),
  factCount: z.number().int().min(0),
});
export type Dossier = z.infer<typeof dossierSchema>;

export interface DossierAnchor {
  id: ObjectId;
  kind: (typeof dossierAnchorKinds)[number];
}

const DEFAULT_BUDGET_TOKENS = 600;
/** chars-per-token heuristic; content is prose, so 4 is conservative. */
const CHARS_PER_TOKEN = 4;

export const composeDossier = (
  anchorName: string,
  facts: Fact[],
  { budgetTokens = DEFAULT_BUDGET_TOKENS }: { budgetTokens?: number } = {}
): string => {
  const budgetChars = budgetTokens * CHARS_PER_TOKEN;
  const header = `# ${anchorName}\n`;

  // Newest first: when the budget runs out, it is the oldest facts that drop.
  const byRecency = [...facts].sort(
    (a, b) => b.updatedAt.getTime() - a.updatedAt.getTime()
  );

  let used = header.length;
  const kept: Fact[] = [];
  for (const fact of byRecency) {
    const line = `- ${fact.text}\n`;
    if (used + line.length > budgetChars) {
      break;
    }
    used += line.length;
    kept.push(fact);
  }

  const sections: string[] = [header];
  for (const category of factCategoryValues) {
    const inCategory = kept.filter((fact) => fact.category === category);
    if (inCategory.length === 0) {
      continue;
    }
    sections.push(
      `\n## ${category}\n${inCategory.map((fact) => `- ${fact.text}`).join("\n")}\n`
    );
  }
  const dropped = facts.length - kept.length;
  if (dropped > 0) {
    sections.push(`\n(+${dropped} older facts beyond the budget)\n`);
  }
  return sections.join("");
};

const anchorFilter = (anchor: DossierAnchor) => {
  switch (anchor.kind) {
    case "engagement":
      return { "anchors.engagementId": anchor.id };
    case "organization":
      return { "anchors.organizationId": anchor.id };
    default:
      return { "anchors.personId": anchor.id };
  }
};

const anchorName = async (
  db: Db,
  tenantId: string,
  anchor: DossierAnchor
): Promise<string> => {
  const { engagements, organizations, people } = getCollections(db);
  if (anchor.kind === "organization") {
    const doc = await organizations.findOne({ _id: anchor.id, tenantId });
    return doc?.name ?? "unknown";
  }
  if (anchor.kind === "person") {
    const doc = await people.findOne({ _id: anchor.id, tenantId });
    return doc?.name ?? "unknown";
  }
  const doc = await engagements.findOne({ _id: anchor.id, tenantId });
  return doc?.title ?? "unknown";
};

export const refreshDossier = async (
  db: Db,
  tenantId: string,
  anchor: DossierAnchor,
  options: { budgetTokens?: number } = {}
): Promise<Dossier | null> => {
  const { dossiers, facts } = getCollections(db);

  const validFacts = await facts
    .find({ tenantId, ...anchorFilter(anchor), ...currentlyValidFilter })
    .sort({ updatedAt: -1 })
    .toArray();

  if (validFacts.length === 0) {
    await dossiers.deleteMany({
      "anchor.id": anchor.id,
      "anchor.kind": anchor.kind,
      tenantId,
    });
    return null;
  }

  const name = await anchorName(db, tenantId, anchor);
  const writtenAt = new Date();
  const doc: Dossier = {
    _id: deterministicId(
      `${tenantId}:dossier:${anchor.kind}:${anchor.id.toHexString()}`
    ),
    anchor,
    content: composeDossier(name, validFacts, options),
    createdAt: writtenAt,
    factCount: validFacts.length,
    tenantId,
    updatedAt: writtenAt,
  };
  await dossiers.updateOne(
    { _id: doc._id, tenantId },
    {
      $set: {
        anchor: doc.anchor,
        content: doc.content,
        factCount: doc.factCount,
        updatedAt: writtenAt,
      },
      $setOnInsert: { createdAt: writtenAt, tenantId },
    },
    { upsert: true }
  );
  return doc;
};

