// End-to-end proof: real AssemblyAI transcript → DeepSeek via AI Gateway →
// ingestion proposal in real Atlas. Uses a separate demo database
// (KNOWLEDGE_MONGODB_DB) so the production "knowledge" db stays untouched.
// Run: set -a; source apps/api/.env.local; set +a
//      KNOWLEDGE_MONGODB_DB=knowledge_e2e_demo bun e2e-extraction.ts
const PKG =
  "/Users/eric/.claude/worktrees/spinor-knowledge-ingestion/packages/knowledge";

const { createGatewayGenerate, getCollections, ObjectId, runExtraction } =
  await import(`${PKG}/index.ts`);
const { getKnowledgeDb } = await import(`${PKG}/client.ts`);

const TENANT = "demo-tenant";
const TRANSCRIPT =
  "Notiz nach dem Telefonat mit Frau Müller von der Nordwind GmbH: Sie bevorzugt Termine am Vormittag. Freitags ist sie nie erreichbar. Entscheidungen trifft die Geschäftsführung gemeinsam. Das Angebot für den Workshop im Oktober soll bis Ende August vorliegen.";

const db = getKnowledgeDb();
console.log(`database: ${db.databaseName}`);
const { proposals, sources } = getCollections(db);

const sourceId = new ObjectId();
await sources.insertOne({
  _id: sourceId,
  capturedBy: "user_eric",
  content: TRANSCRIPT,
  createdAt: new Date(),
  status: "transcribed",
  tenantId: TENANT,
  type: "voice",
  updatedAt: new Date(),
});
console.log(`source: ${sourceId.toHexString()} (transcribed)`);

const result = await runExtraction(db, TENANT, {
  generate: createGatewayGenerate(),
  sourceId,
});
console.log(`extraction: ${result.status} ${result.reason ?? ""}`);

if (result.proposalId) {
  const proposal = await proposals.findOne({ _id: result.proposalId });
  console.log(`\nentity drafts (${proposal?.entityDrafts.length}):`);
  for (const draft of proposal?.entityDrafts ?? []) {
    console.log(`  ${draft.draftId} [${draft.entityType}]`, draft.data);
  }
  console.log(`\nfact drafts (${proposal?.factDrafts.length}):`);
  for (const draft of proposal?.factDrafts ?? []) {
    console.log(
      `  [${draft.category}] (${draft.confidence}) ${draft.text}`,
      draft.anchors
    );
  }
  const source = await sources.findOne({ _id: sourceId });
  console.log(`\nsource status: ${source?.status}`);
}
process.exit(0);

