40	const HEX_ID_REGEX = /^[0-9a-f]{24}$/;
41	
42	export const getProposal = async (
43	  proposalId: string
44	): Promise<ReviewProposal | null> => {
45	  const { orgId } = await auth();
46	  if (!(orgId && HEX_ID_REGEX.test(proposalId))) {
47	    return null;
48	  }
49	  const db = getKnowledgeDb();
50	  const { engagements, facts, organizations, people, proposals, sources } =
51	    getCollections(db);
