53	  const proposal = await proposals.findOne({
54	    _id: new ObjectId(proposalId),
55	    tenantId: orgId,
56	  });
57	  if (!proposal) {
58	    return null;
59	  }
60	
61	  const source = proposal.sourceId
62	    ? await sources.findOne({ _id: proposal.sourceId, tenantId: orgId })
63	    : null;
64	
65	  // Resolve anchor ids to display names, and superseded ids to fact texts.
66	  const anchorIds = proposal.factDrafts.flatMap((draft) =>
67	    [
68	      draft.anchors.engagementId,
69	      draft.anchors.organizationId,
70	      draft.anchors.personId,
71	    ].flatMap((id) => (id ? [id] : []))
72	  );
73	  const supersededIds = proposal.factDrafts.flatMap(
74	    (draft) => draft.supersedes ?? []
75	  );
76	  const [orgDocs, personDocs, engagementDocs, supersededDocs] =
77	    await Promise.all([
78	      organizations
79	        .find({ _id: { $in: anchorIds }, tenantId: orgId })
80	        .toArray(),
81	      people.find({ _id: { $in: anchorIds }, tenantId: orgId }).toArray(),
82	      engagements.find({ _id: { $in: anchorIds }, tenantId: orgId }).toArray(),
83	      facts.find({ _id: { $in: supersededIds }, tenantId: orgId }).toArray(),
84	    ]);
85	  const nameById = new Map<string, string>([
