87	    ...personDocs.map((doc) => [doc._id.toHexString(), doc.name] as const),
88	    ...engagementDocs.map((doc) => [doc._id.toHexString(), doc.title] as const),
89	  ]);
90	  const supersededById = new Map(
91	    supersededDocs.map((doc) => [doc._id.toHexString(), doc.text])
92	  );
93	
94	  const anchorLabel = (draft: (typeof proposal.factDrafts)[number]): string => {
95	    const entityId =
96	      draft.anchors.personId ??
97	      draft.anchors.organizationId ??
98	      draft.anchors.engagementId;
