100	      return nameById.get(entityId.toHexString()) ?? "unknown entity";
101	    }
102	    const draftRef =
103	      draft.anchors.personDraftId ??
104	      draft.anchors.organizationDraftId ??
105	      draft.anchors.engagementDraftId;
106	    return draftRef ? `new: ${draftRef}` : "unanchored";
107	  };
108	
109	  return {
