113	      draftId: draft.draftId,
114	      entityType: draft.entityType,
115	      resolutionStatus: draft.resolution.status,
116	    })),
117	    factDrafts: proposal.factDrafts.map((draft, index) => ({
118	      anchorLabel: anchorLabel(draft),
119	      category: draft.category,
120	      confidence: draft.confidence,
121	      index,
122	      resolutionStatus: draft.resolution.status,
123	      supersedes: (draft.supersedes ?? []).map((id) => ({
124	        id: id.toHexString(),
125	        text: supersededById.get(id.toHexString()) ?? "(fact no longer exists)",
126	      })),
127	      text: draft.text,
128	    })),
129	    id: proposal._id.toHexString(),
130	    kind: proposal.kind,
131	    source: source
132	      ? {
133	          capturedBy: source.capturedBy,
134	          content: source.content ?? "",
