// Seed a reviewable proposal for YOUR Clerk org in the real knowledge db:
// runs the actual extraction (DeepSeek via gateway) on the demo transcript.
// Run: set -a; source apps/api/.env.local; set +a
//      bun seed-review-demo.ts <your-clerk-orgId>
const PKG = "/Users/eric/.claude/worktrees/spinor-review-ui/packages/knowledge";
const { createGatewayGenerate, getCollections, ObjectId, runExtraction } =
  await import(`${PKG}/index.ts`);
const { getKnowledgeDb } = await import(`${PKG}/client.ts`);

const tenantId = process.argv[2];
if (!tenantId) {
  console.error("usage: bun seed-review-demo.ts <clerk-orgId>");
  process.exit(1);
}

const db = getKnowledgeDb();
const { sources } = getCollections(db);
const sourceId = new ObjectId();
await sources.insertOne({
  _id: sourceId,
  capturedBy: "user_eric",
  content:
    "Notiz nach dem Telefonat mit Frau Müller von der Nordwind GmbH: Sie bevorzugt Termine am Vormittag. Freitags ist sie nie erreichbar. Entscheidungen trifft die Geschäftsführung gemeinsam. Das Angebot für den Workshop im Oktober soll bis Ende August vorliegen.",
  createdAt: new Date(),
  status: "transcribed",
  tenantId,
  type: "voice",
  updatedAt: new Date(),
});

const result = await runExtraction(db, tenantId, {
  generate: createGatewayGenerate(),
  sourceId,
});
console.log(`extraction: ${result.status} ${result.reason ?? ""}`);
console.log(
  result.proposalId
    ? `open http://localhost:3000/review — proposal ${result.proposalId.toHexString()}`
    : "no proposal created"
);
process.exit(0);

