1	import type { Db, ObjectId } from "mongodb";
2	import { getCollections } from "./collections";
3	
4	// The transcription stage: voice source audio → AssemblyAI (EU endpoint) →
5	// source.content, ready for extraction. Same operating rules as the
6	// extraction worker: injectable I/O, idempotent progress, and a failure
7	// budget instead of infinite retries.
8	
9	export interface TranscriptResult {
10	  languageCode?: string;
11	  text: string;
12	}
13	
14	export interface RunTranscriptionOptions {
15	  /** Failed attempts before the source flips to "failed". Default 3. */
16	  maxAttempts?: number;
17	  sourceId: ObjectId;
18	  /** The transcription call. Injectable so tests and providers stay decoupled. */
19	  transcribe: (audioUrl: string) => Promise<TranscriptResult>;
20	}
21	
22	export interface TranscriptionRunResult {
23	  reason?: string;
24	  status: "failed" | "retry" | "transcribed";
25	}
26	
27	// Data minimization (GDPR Art. 5): categories a company brain must never
28	// store, redacted at the transcription provider so they never reach the
29	// database. Names, organizations, and money amounts deliberately stay —
30	// they ARE the product's signal.
31	export const DEFAULT_PII_POLICIES = [
32	  "account_number",
33	  "banking_information",
34	  "blood_type",
35	  "credit_card_cvv",
36	  "credit_card_expiration",
37	  "credit_card_number",
38	  "drivers_license",
39	  "drug",
40	  "healthcare_number",
41	  "injury",
42	  "medical_condition",
43	  "medical_process",
44	  "passport_number",
45	  "us_social_security_number",
46	] as const;
47	
48	export interface AssemblyAiConfig {
49	  apiKey?: string;
50	  /** Default: the EU data-residency endpoint. */
51	  baseUrl?: string;
52	  piiPolicies?: readonly string[];
53	  pollIntervalMs?: number;
54	  timeoutMs?: number;
55	}
56	
57	const DEFAULT_BASE_URL = "https://api.eu.assemblyai.com";
58	const DEFAULT_POLL_INTERVAL_MS = 2000;
59	const DEFAULT_TIMEOUT_MS = 180_000;
60	
61	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
62	
63	export const createAssemblyAiTranscriber = (
64	  config: AssemblyAiConfig = {}
65	): ((audioUrl: string) => Promise<TranscriptResult>) => {
66	  const apiKey = config.apiKey ?? process.env.ASSEMBLYAI_API_KEY;
67	  if (!apiKey) {
68	    throw new Error(
69	      "ASSEMBLYAI_API_KEY is required (pass config.apiKey or set the env var)"
70	    );
71	  }
72	  const baseUrl = config.baseUrl ?? DEFAULT_BASE_URL;
73	  const piiPolicies = config.piiPolicies ?? DEFAULT_PII_POLICIES;
74	  const pollIntervalMs = config.pollIntervalMs ?? DEFAULT_POLL_INTERVAL_MS;
75	  const timeoutMs = config.timeoutMs ?? DEFAULT_TIMEOUT_MS;
76	  const headers = { authorization: apiKey };
77	
78	  return async (audioUrl: string): Promise<TranscriptResult> => {
79	    const createRes = await fetch(`${baseUrl}/v2/transcript`, {
80	      body: JSON.stringify({
81	        audio_url: audioUrl,
82	        language_detection: true,
83	        redact_pii: true,
84	        redact_pii_policies: piiPolicies,
85	        redact_pii_sub: "entity_name",
86	        speaker_labels: true,
87	      }),
88	      headers: { ...headers, "content-type": "application/json" },
89	      method: "POST",
90	    });
91	    if (!createRes.ok) {
92	      throw new Error(
93	        `assemblyai ${createRes.status}: ${(await createRes.text()).slice(0, 300)}`
94	      );
95	    }
96	    const created = (await createRes.json()) as { id: string };
97	
98	    const started = Date.now();
99	    for (;;) {
100	      await sleep(pollIntervalMs);
101	      const pollRes = await fetch(`${baseUrl}/v2/transcript/${created.id}`, {
102	        headers,
103	      });
104	      if (!pollRes.ok) {
105	        throw new Error(`assemblyai poll ${pollRes.status}`);
106	      }
107	      const transcript = (await pollRes.json()) as {
108	        error?: string;
109	        language_code?: string;
110	        status: string;
111	        text?: string;
112	      };
113	      if (transcript.status === "completed") {
114	        return {
115	          languageCode: transcript.language_code,
116	          text: transcript.text ?? "",
117	        };
118	      }
119	      if (transcript.status === "error") {
120	        throw new Error(`assemblyai transcription error: ${transcript.error}`);
121	      }
122	      if (Date.now() - started > timeoutMs) {
123	        throw new Error(
124	          `assemblyai transcription timed out after ${timeoutMs}ms`
125	        );
126	      }
127	    }
128	  };
129	};
130	
131	export const runTranscription = async (
132	  db: Db,
133	  tenantId: string,
134	  { maxAttempts = 3, sourceId, transcribe }: RunTranscriptionOptions
135	): Promise<TranscriptionRunResult> => {
136	  const { sources } = getCollections(db);
137	  const source = await sources.findOne({ _id: sourceId, tenantId });
138	  if (!source) {
139	    throw new Error(`Source ${sourceId.toHexString()} not found`);
140	  }
141	  // Already past this stage (including a crashed run that wrote content but
142	  // not the status): nothing to do.
143	  if (source.content && source.status !== "received") {
144	    return { status: "transcribed" };
145	  }
146	  if (source.type !== "voice") {
147	    throw new Error(`Source type "${source.type}" does not need transcription`);
148	  }
149	  if (!(source.status === "received" || source.status === "transcribing")) {
150	    throw new Error(
151	      `Source status "${source.status}" is not transcribable — expected received or transcribing`
152	    );
153	  }
154	  const audioUrl = source.audio?.blobUrl;
155	  if (!audioUrl) {
156	    throw new Error("Voice source has no audio blob to transcribe");
157	  }
158	
159	  await sources.updateOne(
160	    { _id: sourceId, tenantId },
161	    { $set: { status: "transcribing", updatedAt: new Date() } }
162	  );
163	
164	  let failure: string | null = null;
165	  let text = "";
166	  try {
167	    const result = await transcribe(audioUrl);
168	    text = result.text.trim();
169	    if (text.length === 0) {
170	      failure = "transcription returned empty text";
171	    }
172	  } catch (error) {
173	    failure = error instanceof Error ? error.message : String(error);
174	  }
175	
176	  const writtenAt = new Date();
177	  if (failure === null) {
178	    await sources.updateOne(
179	      { _id: sourceId, tenantId },
180	      {
181	        $set: {
182	          content: text,
183	          status: "transcribed",
184	          transcriptionAttempts: 0,
185	          updatedAt: writtenAt,
186	        },
187	        $unset: { error: "" },
188	      }
189	    );
190	    return { status: "transcribed" };
191	  }
192	
193	  const attempts = (source.transcriptionAttempts ?? 0) + 1;
194	  const exhausted = attempts >= maxAttempts;
195	  await sources.updateOne(
196	    { _id: sourceId, tenantId },
197	    {
198	      $set: {
199	        error: failure,
200	        status: exhausted ? "failed" : "received",
201	        transcriptionAttempts: attempts,
202	        updatedAt: writtenAt,
203	      },
204	    }
205	  );
206	  return { reason: failure, status: exhausted ? "failed" : "retry" };
207	};

