16	// The dream cycle: when an anchor accumulates redundant facts, propose
17	// merges through the same review gate as everything else. A merge draft
18	// supersedes ≥2 currently valid facts; on confirmation the review write
19	// path stamps supersededBy and records derivedFrom — nothing here writes
20	// knowledge directly.
21	
22	export interface ConsolidationFact {
23	  category: string;
24	  id: string;
25	  text: string;
26	}
27	
28	const hexObjectId = z.string().regex(/^[0-9a-f]{24}$/);
29	
30	export const llmMergeSchema = z.object({
31	  category: z.enum(factCategoryValues),
32	  confidence: z.number().min(0).max(1),
33	  supersedes: z.array(hexObjectId).min(2),
34	  text: z.string().min(1),
35	});
36	export type LlmMerge = z.infer<typeof llmMergeSchema>;
37	
38	export const llmConsolidationSchema = z.union([
39	  z.strictObject({
40	    reason: z.string().default(""),
41	    skip: z.literal(true),
42	  }),
43	  z.strictObject({
44	    merges: z.array(llmMergeSchema),
45	  }),
46	]);
47	
48	export type ParsedConsolidation =
49	  | { kind: "failure"; reason: string }
50	  | { kind: "merges"; merges: LlmMerge[] }
51	  | { kind: "skip"; reason: string };
52	
53	export const buildConsolidationPrompt = ({
54	  anchorName,
55	  facts,
56	}: {
57	  anchorName: string;
58	  facts: ConsolidationFact[];
59	}): string => {
60	  const factLines = facts
61	    .map((fact) => `${fact.id} | ${fact.category} | ${fact.text}`)
62	    .join("\n");
63	
64	  return `You consolidate a company knowledge base. Below are the currently valid facts about "${anchorName}". Reviewers confirm every merge, so propose only merges that reduce redundancy with ZERO information loss — every detail, name, number, and causal link must survive into the merged text.
65	
66	Facts (id | category | text):
67	${factLines}
68	
69	Return ONLY JSON, no markdown fences, in exactly one of these two shapes:
70	
71	1. Redundancy found:
72	{"merges": [{"text": "<merged fact, one self-contained sentence in the facts' language>", "category": "...", "confidence": 0.0-1.0, "supersedes": ["<fact id>", "<fact id>"]}]}
73	
74	2. Nothing worth merging:
75	{"skip": true, "reason": "..."}
76	
77	Rules:
78	- A merge must supersede at least TWO of the facts above, and only ids from the list may appear.
79	- No fact id may appear in more than one merge.
80	- Merge only facts that describe the same subject; never merge unrelated facts into a grab-bag sentence.
81	- Do not invent, embellish, or drop information — compress wording, not meaning.
82	- Categories: ${factCategoryValues.join(" | ")}.`;
83	};
84	
85	export const parseConsolidationResponse = (
86	  raw: string
87	): ParsedConsolidation => {
88	  const text = stripFences(raw);
89	  if (REFUSAL_REGEX.test(text)) {
90	    return { kind: "failure", reason: `model refused: ${text.slice(0, 200)}` };
91	  }
92	  const data = extractLastValidObject(text, llmConsolidationSchema);
93	  if (data === undefined) {
94	    return {
95	      kind: "failure",
96	      reason: `no schema-valid JSON object in reply: ${text.slice(0, 200)}`,
97	    };
98	  }
99	  if ("skip" in data) {
100	    return { kind: "skip", reason: data.reason };
101	  }
102	  if (data.merges.length === 0) {
103	    return { kind: "skip", reason: "no merges proposed" };
104	  }
105	  return { kind: "merges", merges: data.merges };
106	};
