123	const anchorFilter = (anchor: DossierAnchor) => {
124	  switch (anchor.kind) {
125	    case "engagement":
126	      return { "anchors.engagementId": anchor.id };
127	    case "organization":
128	      return { "anchors.organizationId": anchor.id };
129	    default:
130	      return { "anchors.personId": anchor.id };
131	  }
132	};
133	
134	const anchorDraftField = (anchor: DossierAnchor) => {
135	  switch (anchor.kind) {
136	    case "engagement":
137	      return { engagementId: anchor.id };
138	    case "organization":
139	      return { organizationId: anchor.id };
140	    default:
141	      return { personId: anchor.id };
142	  }
143	};
144	
145	// The model may only merge ids it was shown, each at most once.
146	const validateMerges = (
147	  merges: LlmMerge[],
148	  shownIds: Set<string>
149	): string | null => {
150	  const claimed = new Set<string>();
151	  for (const [index, merge] of merges.entries()) {
152	    for (const id of merge.supersedes) {
153	      if (!shownIds.has(id)) {
154	        return `merges[${index}] supersedes unknown fact id ${id}`;
155	      }
156	      if (claimed.has(id)) {
157	        return `merges[${index}] supersedes fact ${id}, which another merge already claims`;
158	      }
159	      claimed.add(id);
160	    }
161	  }
162	  return null;
163	};
