// Live dream-cycle test: seed redundant facts → sweepConsolidation with the
// real gateway → inspect the merge proposal. Demo db only.
const PKG = "/Users/eric/conductor/workspaces/spinor/tacoma/packages/knowledge";
const { createGatewayGenerate, getCollections, ObjectId, sweepConsolidation } =
  await import(`${PKG}/index.ts`);
const { getKnowledgeDb } = await import(`${PKG}/client.ts`);

const db = getKnowledgeDb();
console.log(`database: ${db.databaseName}`);
const { facts, organizations, proposals } = getCollections(db);
const TENANT = "demo-tenant";
const orgId = new ObjectId();
const now = () => ({ createdAt: new Date(), updatedAt: new Date() });

await organizations.insertOne({
  _id: orgId, domains: [], name: "Nordwind GmbH", status: "active", tenantId: TENANT, ...now(),
});
const texts = [
  "Frau Müller bevorzugt Termine am Vormittag.",
  "Termine mit Frau Müller bitte vormittags legen.",
  "Frau Müller ist freitags nie erreichbar.",
  "Freitags keine Termine mit Frau Müller vereinbaren.",
  "Entscheidungen trifft die Geschäftsführung gemeinsam.",
  "Die Geschäftsführung entscheidet immer im Konsens.",
  "Das Angebot für den Oktober-Workshop soll bis Ende August vorliegen.",
  "Rechnungen bitte immer als PDF senden.",
];
for (const text of texts) {
  await facts.insertOne({
    _id: new ObjectId(), anchors: { organizationId: orgId },
    category: "preference", confidence: 0.85, confirmedBy: "user_eric",
    sourceId: new ObjectId(), tenantId: TENANT, text, ...now(),
  });
}
console.log(`seeded ${texts.length} redundant facts for Nordwind GmbH`);

const report = await sweepConsolidation(db, { generate: createGatewayGenerate() });
console.log("sweep report:", JSON.stringify(report));

const proposal = await proposals.findOne({ kind: "consolidation", status: "open", tenantId: TENANT });
if (proposal) {
  console.log(`\nmerge proposal ${proposal._id.toHexString()}:`);
  for (const draft of proposal.factDrafts) {
    console.log(`  [${draft.category}] "${draft.text}"  (merges ${draft.supersedes?.length} facts)`);
  }
}
process.exit(0);
EOF
